window.kbPageData["views/entry/k-35e86ef7d63779d5"] = {"key":"entry/k-35e86ef7d63779d5","state":{"route":"entry/k-35e86ef7d63779d5"},"node":{"id":"k-35e86ef7d63779d5","mode":"k","title":"指导思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["公报解读正文"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"三、指导思想\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小\n平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思\n想，深入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，\n以党章为根本，坚持党的先锋队性质，坚持党的全…","sources":[{"id":"f6c7e3e05b194754","label":"指导思想","topic":"二十届五中全会","category":"时政","text":"三、指导思想\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小\n平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思\n想，深入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，\n以党章为根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提\n高党的长期执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的\n基调不动摇，健全全面从严治党体系，以党的政治建设①为统领，全面推进党的各方面建设，\n充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提\n高②，持续增强党的政治领导力、思想引领力、群众组织力、社会号召力③，确保党始终成为\n走在时代前列、人民衷心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终\n成为中国特色社会主义事业的坚强领导核心。","source":{"doc":"41195a191a57c1c36332","first":10,"last":10,"page":10,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-35e86ef7d63779d5":[]}};
